<?php
class TeamController {
 public function index():void {Security::role(['owner','manager']);$rows=db_all('SELECT id,name,email,phone,role,status,created_at FROM users WHERE company_id=? ORDER BY id DESC',[company_id()]);View::render('business/team',compact('rows'));}
 public function save():void {Security::role(['owner']);verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$role=$_POST['role']??'cashier';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10||!in_array($role,['manager','cashier'],true)){flash('error','Vérifiez les informations. Mot de passe de 10 caractères minimum.');redirect('/team');}if(db_one('SELECT id FROM users WHERE email=?',[$email])){flash('error','Cet e-mail est déjà utilisé.');redirect('/team');}$max=(int)(db_one('SELECT p.max_users FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.company_id=? AND s.status IN ("active","trial") ORDER BY s.id DESC LIMIT 1',[company_id()])['max_users']??1);$n=(int)(db_one('SELECT COUNT(*) n FROM users WHERE company_id=?',[company_id()])['n']??0);if($n >= $max){flash('error','Limite de comptes atteinte pour votre offre.');redirect('/subscription');}db_exec('INSERT INTO users(company_id,name,email,password,role,status,created_at) VALUES(?,?,?,?,?,"active",NOW())',[company_id(),$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);Security::audit('team.user_created','user',null,['email'=>$email,'role'=>$role]);flash('success','Utilisateur ajouté.');redirect('/team');}
 public function status():void {Security::role(['owner']);verify_csrf();$id=(int)($_POST['id']??0);if($id===(int)Auth::user()['id']){flash('error','Vous ne pouvez pas suspendre votre propre compte.');redirect('/team');}Database::p()->prepare('UPDATE users SET status=IF(status="active","suspended","active") WHERE id=? AND company_id=? AND role<>"owner"')->execute([$id,company_id()]);Security::audit('team.user_status_changed','user',$id);redirect('/team');}
}
